INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l21',3,5,21,'Daniel Mendoza','丹尼尔·门多萨','综合复习难点:not ... until(直到…才)、rise(rose,不接名词)与 raise(raised,后接一个东西)的区别、ago(相对现在)与 before(相对过去)、could(过去的一般能力/可能)与 was able to(某一次成功做成)、被动语态施动者 by、形容词 + 动词不定式(pleased to / sorry to)(原创承载 NCE3 L21 考点·真实历史人物传记·适度淡化:把''赤手拳击可能致死''的血腥略去,突出门多萨''把蛮打变成讲技巧的运动''与''挥霍致穷''的理财警示)','两百年前,拳击是英格兰最受欢迎的运动之一,但那时的拳击和今天大不一样:拳手不戴手套,几乎没有规则。直到1860年,一位贵族才拟出第一套正规规则,拳套也才被引入。不过早在那之前,就有一位拳手开始把粗野的打斗变成一门真正的技艺,他叫丹尼尔·门多萨,生于1764年。门多萨很年轻就成了名。他身手敏捷、头脑聪明、步法轻盈,给拳台带来一种“科学”,主张脑子和力气一样重要。在他那个年代,他红极一时,受到贫富一致的爱戴。当时英格兰最杰出的拳手理查德·汉弗莱斯提出要训练他,可这徒弟学得太快,两人很快成了对手。门多萨两次败给汉弗莱斯,直到1790年才终于赢下,被封为英格兰冠军。此后门多萨开了一所著名的拳击学校,连拜伦勋爵都来学艺;他一场比赛就能挣一大笔钱。可惜他太爱挥霍,总也攒不下钱。渐渐地他债台高筑;在被一位更年轻的拳手击败后,人群把他忘了。他在贫困中度过晚年——这提醒人们:光有天赋,弥补不了花钱的大手大脚。','{"q":"Listen and answer — How many times did Mendoza lose to Humphries before finally winning?","options":["Twice","Once","Three times","He never lost"],"answer_index":0}'::jsonb,'{"title":"not...until / rise vs raise / ago vs before / could vs was able to","intro":"①not ... until“直到…才”:强调句 It was not until 1790 that he won。②rise(rose, risen)表“上升、成名”,后面不接一个东西;raise(raised)表“举起、抬高”,后面要接一个东西:The sun rises. / He raised his hand.③ago 从“现在”往前数(two hundred years ago);before 从“过去某点”往前数(years before he met her)。④could 表“过去的一般能力/可能”;某一次“终于做成”用 was able to。⑤被动语态里动作的发出者用 by 引出;pleased/sorry 等形容词后接 to do。","table":{"headers":["用法","意思","例子"],"rows":[["not ... until","直到…才","Gloves were not used until 1860."],["rise(rose) / raise(raised)","上升,成名 / 举起","He rose to fame. / He raised his fists."],["ago / before","(距今)…前 / (在过去某点)…前","two hundred years ago / years before"],["could / was able to","过去的能力 / 某次成功","could get hurt / was able to win"]]},"specialRules":[{"rule":"rise 后面不接一个东西(rise to fame, the sun rises);raise 后面一定要接一个东西(raise your hand, raise money)。别混。","mark":"rise / raise"},{"rule":"肯定句里“某一次终于办到”用 was able to,不用 could;could 用于“过去的一般能力/可能”。","mark":"could / was able to"},{"rule":"美式拼写:defense(英式 defence)、favorite(英式 favourite)、honor(英式 honour)、practice 作动词(英式 practise)。","mark":"defense / favorite"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l21',1,NULL,'Two hundred years ago, boxing was one of the most popular sports in England, though it looked nothing like the sport we know today. Fighters used no gloves, and there were almost no rules. Gloves were not introduced until 1860, when a nobleman drew up the first proper set of regulations.','两百年前,拳击是英格兰最受欢迎的运动之一,但那时的拳击和今天大不一样:拳手不戴手套,几乎没有规则。直到1860年,一位贵族才拟出第一套正规规则,拳套也才被引入。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l21',2,NULL,'One boxer, however, had already begun to turn rough fighting into a real skill long before then. His name was Daniel Mendoza, and he was born in 1764. Mendoza rose to fame very young. He was quick, clever, and light on his feet, and he brought a kind of ''science'' to the ring, teaching that brains mattered as much as strength.','不过早在那之前,就有一位拳手开始把粗野的打斗变成一门真正的技艺,他叫丹尼尔·门多萨,生于1764年。门多萨很年轻就成了名。他身手敏捷、头脑聪明、步法轻盈,给拳台带来一种“科学”,主张脑子和力气一样重要。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l21',3,NULL,'In his day he was enormously popular; he was admired by rich and poor alike. Richard Humphries, then the most eminent boxer in England, offered to train him, but the pupil learned so fast that the two soon became rivals. Mendoza lost to Humphries twice before he was finally able to beat him in 1790 and be crowned Champion of England.','在他那个年代,他红极一时,受到贫富一致的爱戴。当时英格兰最杰出的拳手理查德·汉弗莱斯提出要训练他,可这徒弟学得太快,两人很快成了对手。门多萨两次败给汉弗莱斯,直到1790年才终于赢下,被封为英格兰冠军。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l21',4,NULL,'Mendoza then opened a famous academy, where even Lord Byron came to learn, and he earned huge sums for a single match. Sadly, he was so extravagant that he could never hold on to his money.','此后门多萨开了一所著名的拳击学校,连拜伦勋爵都来学艺;他一场比赛就能挣一大笔钱。可惜他太爱挥霍,总也攒不下钱。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l21',5,NULL,'Little by little he fell into debt, and after he was defeated by a younger fighter, the crowds forgot him. He spent his last years in poverty, a reminder that talent alone cannot make up for careless spending.','渐渐地他债台高筑;在被一位更年轻的拳手击败后,人群把他忘了。他在贫困中度过晚年——这提醒人们:光有天赋,弥补不了花钱的大手大脚。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
